"""Aplica a direção visual final e os ajustes aprovados à página gerada."""
import re

def apply(doc):
    def replace_section(n, body):
        nonlocal doc
        pat=r'(<section class="section[^\"]*" id="bloco-'+str(n)+r'">).*?</section>'
        doc=re.sub(pat,lambda m:m.group(1)+'<div class="wrap">'+body+'</div></section>',doc,flags=re.S)
    def label(n,text): return f'<p class="eyebrow"><span>{n:02}</span> {text}</p>'
    def cta(text='Quero abrir meu CNPJ com 30% OFF',kind='opening'):
        return f'<button type="button" class="cta {"outline" if kind!="opening" else ""}" data-action="{kind}">{text}<span aria-hidden="true">↗</span></button>'
    stamp='<img class="stamp" src="assets/carimbo-30-off.svg" width="320" height="320" alt="Oferta especial: 30% OFF na abertura de CNPJ">'
    disclaimer='<p class="payment-note">*Parcela ilustrativa. O valor pode sofrer acréscimos conforme a quantidade de parcelas e as condições exibidas no checkout.</p>'
    fees='<p class="payment-note">*O valor refere-se aos honorários de abertura e não inclui taxas da OAB, Prefeitura e demais órgãos, pagas à parte.</p>'
    price='<div class="installment-price"><span>Em até <b data-installments>6x</b> de</span><strong data-installment>R$ 70<sup>*</sup></strong></div><p class="cash-price">De <s data-original>R$ 600</s> por <b data-total>R$ 420</b> no Pix ou boleto.</p>'
    hero='''<section class="hero"><div class="wrap hero-inner"><div class="hero-copy"><img class="campaign-logo" src="assets/logo-campanha.png" width="2172" height="724" alt="Black Friday 2026 Advventure Contabilidade"><p class="eyebrow hero-eyebrow">SUPER BLACK FRIDAY ANTECIPADA</p><h1>Advogado(a), entre em 2027 com o <em>regime tributário certo.</em></h1><p class="hero-sub">Abrir CNPJ é burocrático, mas não precisa ser caro. Na Black Friday antecipada da Advventure, você faz isso com <strong>30% de desconto.</strong></p>'''+price+'<div class="hero-actions">'+cta()+'</div>'+disclaimer+fees+'''<button class="migration-callout" data-action="migration"><span>JÁ TEM CNPJ?</span><strong>Migre com o 1º mês de contabilidade grátis.</strong><b aria-hidden="true">↗</b></button><p class="hero-proof">Feita de advogados para advogados · Idealizada por Gabriel Quintanilha · Convênio com 4 seccionais da OAB</p></div><div class="hero-art"><div class="halo"></div><img class="gabriel-hero" src="assets/gabriel-sorriso-recortado.png" alt="Gabriel Quintanilha sorrindo, de terno azul e gravata vermelha" width="1024" height="1536" fetchpriority="high">'''+stamp+'''<div class="expert-label"><strong>Gabriel Quintanilha</strong><span>Mais de 20 anos na advocacia tributária</span></div></div></div></section>'''
    doc=re.sub(r'<section class="hero">.*?</section>',lambda m:hero,doc,count=1,flags=re.S)
    doc=doc.replace('6x sem juros','em até 6x').replace('6X SEM JUROS','EM ATÉ 6X').replace('6x sem juros','em até 6x')
    # Contexto visual para a virada do ano.
    doc=doc.replace('<section class="section tonal" id="bloco-1"><div class="wrap">','<section class="section tonal" id="bloco-1"><div class="wrap">')
    marker='</div></div></section><section class="section " id="bloco-2">'
    doc=doc.replace(marker,'</div><figure class="calendar-visual"><img src="assets/janeiro-2027.png" width="1672" height="941" loading="lazy" alt="Calendário de janeiro de 2027 em uma mesa, com o Congresso Nacional ao fundo"><figcaption>2027 COMEÇA COM AS DECISÕES QUE VOCÊ TOMA AGORA.</figcaption></figure></div></section><section class="section " id="bloco-2">',1)
    # Comparação de estruturas com escolhas interativas.
    panel='''<div class="structure-guide"><div class="structure-text"><p class="eyebrow">A ADVVENTURE ENTENDE A SUA ROTINA</p><h3>CNPJ técnico e sociedade são caminhos diferentes.</h3><p>Escolha uma opção para entender o que muda na estrutura.</p><div class="model-tabs" role="group" aria-label="Entender as estruturas"><button type="button" data-model="technical" aria-pressed="true">CNPJ técnico</button><button type="button" data-model="company" aria-pressed="false">Sociedade de advocacia</button></div><div class="model-explanation" id="model-explanation" aria-live="polite"><strong>Você continua pessoa física.</strong><p>É uma inscrição para fins cadastrais e fiscais. Ela não transforma você em uma sociedade nem dá acesso ao Simples Nacional.</p></div></div><figure class="lawyer-crop after"><img src="assets/advogado-comparativo.png" width="2172" height="724" loading="lazy" alt="Imagem ilustrativa de profissional organizando a rotina em seu escritório"><figcaption>IMAGEM ILUSTRATIVA</figcaption></figure></div>'''
    doc=re.sub(r'(<section class="section " id="bloco-2">.*?</h2>)',lambda m:m.group(1)+panel,doc,count=1,flags=re.S)
    # Simulador sem cadastro, inteiramente local e com premissas explícitas.
    simulator='''<div class="sim-heading"><div>'''+label(3,'SIMULADOR DE ECONOMIA')+'''<h2>A conta que ninguém faz com você.<br><em>Agora, faça a sua.</em></h2></div><p>Mude o valor dos seus honorários e compare o IRPF com o DAS de uma sociedade no Simples. Sem cadastro.</p></div><div class="calculator"><div class="calculator-input"><label for="revenue">Quanto você recebe por mês em honorários?</label><div class="money-field"><span>R$</span><input id="revenue" type="number" inputmode="decimal" min="1" max="50000" step="0.01" value="20000" aria-describedby="revenue-help revenue-error"></div><p id="revenue-help">Informe uma média mensal. Faixa desta comparação: R$ 1 a R$ 50 mil.</p><div class="amount-options"><button type="button" data-amount="5000">R$ 5 mil</button><button type="button" data-amount="10000">R$ 10 mil</button><button type="button" data-amount="20000" aria-pressed="true">R$ 20 mil</button><button type="button" data-amount="30000">R$ 30 mil</button></div><label class="range-label" for="revenue-range">Ajustar honorários</label><input id="revenue-range" type="range" min="1000" max="50000" step="500" value="20000" aria-label="Ajustar honorários mensais"><p id="revenue-error" role="alert"></p><p class="calc-context">A decisão começa com uma conta.<br><strong>A estrutura certa depende de você.</strong></p></div><div class="calculator-results" id="calc-results"><div class="result-columns"><div class="cpf"><span>NO CPF · IRPF</span><strong id="ir-result">R$ 4.424,29</strong><small>Por mês, com desconto simplificado</small></div><div class="cnpj"><span>NO CNPJ · DAS</span><strong id="das-result">R$ 1.125,00</strong><small id="effective-rate">Anexo IV · 5,625% efetiva</small></div></div><div class="calculated-difference" aria-live="polite"><span id="difference-label">DIFERENÇA MENSAL ILUSTRATIVA</span><strong id="difference-result">R$ 3.299,29</strong><p id="annual-result">R$ 39.591,48 em 12 meses no mesmo cenário.</p></div><p class="note">Comparação parcial de tributos, sem despesas dedutíveis, outros rendimentos ou INSS no CPF. No CNPJ, não inclui CPP, INSS e IR sobre pró-labore, contabilidade, taxas e outros custos. A diferença não equivale à economia líquida total.</p></div></div><details class="calculation-method"><summary>Ver premissas e referências do simulador</summary><p>Referência: tabela mensal do IRPF de 2026, com desconto simplificado de R$ 607,20 e redução mensal aplicável. DAS calculado pelo Anexo IV, com receita constante e receita de referência igual a 12 vezes os honorários mensais. Não projeta automaticamente regras futuras de 2027. Renda anual total acima de R$ 600 mil, lucros distribuídos acima de R$ 50 mil no mês e casos específicos exigem análise individual.</p><p><a href="https://www.gov.br/receitafederal/pt-br/assuntos/meu-imposto-de-renda/tabelas/2026" target="_blank" rel="noopener">Receita Federal · IRPF 2026</a> · <a href="https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp123.htm" target="_blank" rel="noopener">LC 123/2006 · Anexo IV</a></p></details><div class="section-action">'''+cta('Quero avaliar minha estrutura e abrir meu CNPJ')+'</div>'
    replace_section(3,simulator)
    # Imagens ilustrativas nas duas trilhas.
    doc=doc.replace('<span class="path-no">01 / ABERTURA</span>','<figure class="lawyer-crop before"><img src="assets/advogado-comparativo.png" width="2172" height="724" loading="lazy" alt="Imagem ilustrativa de profissional com documentos acumulados"><figcaption>SEM UMA ROTINA CONTÁBIL ORGANIZADA · ILUSTRAÇÃO</figcaption></figure><span class="path-no">01 / ABERTURA</span>')
    doc=doc.replace('<span class="path-no">02 / MIGRAÇÃO</span>','<figure class="lawyer-crop after"><img src="assets/advogado-comparativo.png" width="2172" height="724" loading="lazy" alt="Imagem ilustrativa de profissional acompanhando sua rotina contábil"><figcaption>COM ORGANIZAÇÃO E ACOMPANHAMENTO · ILUSTRAÇÃO</figcaption></figure><span class="path-no">02 / MIGRAÇÃO</span>')
    # Pagamento, contrato e agendamento: sem prazo inventado.
    steps=['Faça o pagamento. Após ativarmos a campanha, o botão leva ao checkout seguro do Asaas. Confira o valor e a forma de pagamento antes de concluir.','Receba o contrato por e-mail. Confira as condições e siga as orientações para assinatura.','Receba uma mensagem para agendar o onboarding. A equipe combina o horário com você e orienta o envio da documentação.','A Advventure cuida da formalização. Registro na OAB, CNPJ, Prefeitura e enquadramento fiscal, conforme o seu caso.']
    old=re.search(r'(<div class="process-grid"><div><h3>Abertura de CNPJ</h3>).*?</ol>',doc,re.S)
    if old: doc=doc[:old.start()]+old.group(1)+'<ol class="steps">'+''.join('<li>'+s+'</li>' for s in steps)+'</ol>'+doc[old.end():]
    # Bio atualizada e selos originais fornecidos.
    bio=label(7,'GABRIEL QUINTANILHA · IDEALIZADOR DA ADVVENTURE')+'''<div class="authority"><div class="authority-photo"><img src="assets/gabriel-sorriso-recortado.png" width="1024" height="1536" loading="lazy" alt="Gabriel Quintanilha sorrindo, idealizador da Advventure"><span>GABRIEL QUINTANILHA<br><small>Advocacia tributária na prática, há mais de 20 anos.</small></span></div><div><h2>Idealizada por quem vive o <em>Direito Tributário todos os dias.</em></h2><p>Quando o assunto é Reforma Tributária, aparece muito “especialista” da noite para o dia. Gabriel Quintanilha não é um deles.</p><p>Gabriel tem como atividade principal a advocacia tributária há mais de 20 anos, em casos reais, para empresas reais. É autor de “Reforma Tributária Brasileira: Tributos sobre o Consumo” (Editora Método/GEN).</p><div class="best-callout"><strong>7</strong><span>ANOS CONSECUTIVOS<br><b>Reconhecido pela Best Lawyers · 2020 a 2026</b></span></div><ul class="credentials"><li>Um dos melhores advogados tributaristas do Brasil pela Best Lawyers.</li><li>Professor e Coordenador de Direito Tributário na FGV.</li><li>Doutor em Direito (UVA-RJ) e Mestre em Economia (UCAM-RJ).</li><li>Extensão em Tributação Internacional pela Universiteit Leiden, na Holanda.</li></ul></div></div><div class="awards"><p class="eyebrow">RECONHECIMENTO DE 2020 A 2026</p><img src="assets/best-lawyers-2020-2026.png" width="2172" height="724" loading="lazy" alt="Selos Best Lawyers de 2020, 2021, 2022, 2023, 2024, 2025 e 2026"></div><details class="full-bio"><summary>Conheça mais sobre a trajetória do Gabriel</summary><ul class="credentials"><li>Autor do “Manual de Direito Tributário — Volume Único” (Método) e do “Mandado de Segurança no Direito Tributário” (Saraiva).</li><li>Professor no IBMEC, UFF, UERJ, EMERJ e na Escola Superior de Advocacia da OAB/RJ.</li><li>Sócio fundador do Gabriel Quintanilha Advogados, com atuação no RJ, SP e RS.</li><li>Idealizador do Expert em Tributário e do podcast Tributologia.</li></ul></details>'''
    replace_section(7,bio)
    # Oferta: parcela em destaque; total secundário.
    doc=re.sub(r'<p class="old-price">De <s>R\$ 600</s> por</p><div class="offer-price">.*?</div><p class="installments">.*?</p>',lambda m:price+disclaimer+fees,doc,count=1,flags=re.S)
    doc=doc.replace('<span class="offer-tag">ABERTURA DE CNPJ · 30% OFF</span>','<div class="offer-head"><span class="offer-tag">ABERTURA DE CNPJ</span>'+stamp+'</div>')
    # Reforço de campanha sem poluir a leitura.
    ribbon='<div class="offer-ribbon"><div>'+stamp+'</div><p>O próximo passo do seu escritório<br><strong>começa antes de janeiro.</strong></p>'+cta('Aproveitar 30% OFF na abertura')+'</div>'
    doc=re.sub(r'(<section class="section tonal" id="bloco-5">.*?)(</div></section>)',lambda m:m.group(1)+ribbon+m.group(2),doc,count=1,flags=re.S)
    doc=doc.replace('Sim, em até 6x de R$ 70 sem juros no cartão de crédito.','Sim. Você pode pagar em até 6x no cartão. A referência de R$ 70 por parcela é ilustrativa e pode sofrer acréscimos conforme o parcelamento e as condições do checkout. O pagamento também pode ser feito por Pix ou boleto.')
    doc=doc.replace('em até 6x sem juros no cartão','em até 6x no cartão, sujeito às condições do checkout')
    faq='<details><summary>O que acontece depois do pagamento?</summary><p>Você recebe o contrato por e-mail e, em seguida, uma mensagem da equipe para agendar o onboarding. Nesse encontro, a Advventure orienta os próximos passos e os documentos necessários.</p></details><details><summary>O preço da abertura inclui as taxas oficiais?</summary><p>Não. O honorário do serviço de abertura não se confunde com as taxas da OAB, Prefeitura e demais órgãos. Essas taxas são cobradas à parte, conforme a sua seccional e município.</p></details>'
    doc=re.sub(r'(<section class="section tonal" id="bloco-13">.*?<div class="accordion">)',lambda m:m.group(1)+faq,doc,count=1,flags=re.S)
    doc=doc.replace('<div class="closing">','<div class="closing">'+stamp)
    # Vocativo inclusivo onde a copy se dirige diretamente ao visitante.
    doc=doc.replace('Advogado,','Advogado(a),').replace('advogado,','advogado(a),')
    doc=doc.replace('Só atende advogado','Só atende advogados(as)').replace('só atende advogado','só atende advogados(as)').replace('cada advogado','cada advogado(a)').replace('Mesmo advogado,','Mesmo advogado(a),')
    # Todas as ações têm destinos separados e editáveis.
    def actions(m):
        classes,body=m.group(1),m.group(2)
        kind='migration' if re.search('migr|consultor',body,re.I) else 'opening'
        return '<button type="button" class="'+classes+'" data-action="'+kind+'">'+body+'</button>'
    doc=re.sub(r'<button type="button" class="([^"]*)" data-preview>(.*?)</button>',actions,doc,flags=re.S)
    doc=doc.replace('<script src="app.js" defer></script>','<script src="config.js" defer></script><script src="calculo.js" defer></script><script src="app.js" defer></script>')
    doc=doc.replace('<aside class="review-mode"','<button class="floating-consultant" type="button" data-action="consultant"><span class="chat-mark" aria-hidden="true"></span>Conversar com um consultor</button><aside class="review-mode"')
    doc=doc.replace('<link rel="stylesheet" href="style.css">','<link rel="preload" href="assets/fonts/anton.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="final.css">')
    doc=doc.replace('sem juros','conforme condições do checkout').replace('SEM JUROS','CONFORME CONDIÇÕES DO CHECKOUT')
    doc=re.sub(r'\b([Aa])dvogado\b(?!\(a\))',r'\1dvogado(a)',doc)
    doc=re.sub(r'\b([Aa])dvogados\b(?!\(as\))',r'\1dvogados(as)',doc)
    doc=doc.replace('Gabriel Quintanilha Advogados(as)','Gabriel Quintanilha Advogados')
    # Retificações finais: capa apenas com benefícios, valores exclusivos da oferta.
    doc=doc.replace('assets/advogado(a)-comparativo.png','assets/advogado-comparativo.png')
    hero_match=re.search(r'<section class="hero">.*?</section>',doc,re.S)
    revised=hero_match.group(0)
    revised=re.sub(r'<div class="installment-price">.*?</div><p class="cash-price">.*?</p>','',revised,flags=re.S)
    revised=re.sub(r'<p class="payment-note">.*?</p>','',revised,flags=re.S)
    revised=revised.replace('Na Black Friday antecipada da Advventure, você faz isso com <strong>30% de desconto.</strong>','Na Black Friday antecipada da Advventure, abra seu CNPJ com <strong>30% de desconto.</strong> Ou migre da contabilidade tradicional para uma contabilidade especializada na sua profissão, com <strong>o primeiro mês por nossa conta.</strong>')
    revised=revised.replace('Migre com o 1º mês de contabilidade grátis.','Migre com o 1º mês por nossa conta. Você só paga a partir do 2º mês.')
    doc=doc[:hero_match.start()]+revised+doc[hero_match.end():]
    doc=doc.replace('<figure class="lawyer-crop after"><img src="assets/advogado-comparativo.png" width="2172" height="724" loading="lazy" alt="Imagem ilustrativa de profissional organizando a rotina em seu escritório">','<figure class="structure-photo"><img src="assets/estrutura-contabil.png" width="1536" height="1024" loading="lazy" alt="Imagem ilustrativa de documentos sendo revisados em uma mesa de trabalho">')
    doc=doc.replace('<div class="authority-photo"><img src="assets/gabriel-sorriso-recortado.png" width="1024" height="1536"','<div class="authority-photo"><img src="assets/gabriel-serio.jpeg" width="1066" height="1600"').replace('alt="Gabriel Quintanilha sorrindo, idealizador da Advventure"','alt="Gabriel Quintanilha, idealizador da Advventure, com as mãos entrelaçadas"')
    doc=doc.replace('Sim. Você pode pagar em até 6x no cartão. A referência de R$ 70 por parcela é ilustrativa e pode sofrer acréscimos conforme o parcelamento e as condições do checkout. O pagamento também pode ser feito por Pix ou boleto.','Consulte as formas de pagamento, valores e condições na seção de ofertas e no checkout. O parcelamento no cartão tem juros, que serão informados antes da conclusão do pagamento.')
    doc=doc.replace('É burocrático, mas não precisa ser caro. Na Black Friday o honorário cai de R$ 600 para R$ 420, em até 6x no cartão, sujeito às condições do checkout, e toda a burocracia fica com a gente.','É burocrático, mas não precisa ser caro. Na Black Friday, você tem 30% de desconto nos honorários de abertura, e a burocracia fica com a gente. Consulte os valores e as condições na seção de ofertas.')
    doc=doc.replace('*Parcela ilustrativa. O valor pode sofrer acréscimos conforme a quantidade de parcelas e as condições exibidas no checkout.','*Parcela de R$ 70 apenas como referência provisória. O parcelamento no cartão tem juros. O valor final das parcelas será informado no checkout, conforme a quantidade escolhida.')
    doc=re.sub(r'É burocrático, mas não precisa ser caro\.[^<]*','É burocrático, mas não precisa ser caro. Na Black Friday, você tem 30% de desconto nos honorários de abertura, e a burocracia fica com a gente. Consulte os valores e as condições na seção de ofertas.',doc)
    doc=doc.replace('R$ 189 (R$ 159 com convênio OAB)','Consulte as condições na seção de ofertas')
    doc=doc.replace('EM ATÉ 6X <b>●</b>','CONTABILIDADE ESPECIALIZADA <b>●</b>')
    return doc.replace('src="app.js"','src="final-app.js"').replace('assets/advogado(a)-comparativo.png','assets/advogado-comparativo.png').replace('<div class="awards">','<div class="awards" role="region" aria-label="Reconhecimentos Best Lawyers de 2020 a 2026" tabindex="0">')
